export const names = rows.trim().split('\n').map((row, index) => {
  const [group, ar, ru, latin, ruMeaning, enMeaning, ruNote, enNote, ruCue, enCue, refs] = row.split('|');
  return {
    id: index + 1, group, ar, ru, latin,
    meaning: [ruMeaning, enMeaning], note: [ruNote, enNote], cue: [ruCue, enCue],
    variants: variants[index + 1] || [[], []],
    refs: refs === '-' ? [] : refs.split(',')
  };
});
export const byId = new Map(names.map(name => [name.id, name]));
export const related = name => [...new Set([
  ...names.filter(other => other.group === name.group && other.id !== name.id).map(other => other.id),
  ...crossLinks.filter(pair => pair.includes(name.id)).map(pair => pair.find(id => id !== name.id))
])].map(id => byId.get(id));

export function sourceLink(ref) {
  if (/^[hk]:/.test(ref)) {
    const [type, book, number] = ref.split(':');
    return { type, label: `${book} ${number}`, url: `https://sunnah.com/${book}:${number}` };
  }
  return { type: ref[0], label: ref.slice(1), url: `https://quran.com/${ref.slice(1).replace(':', '/')}` };
}
